        memset(matchPos, -1, sizeof(matchPos));
        memset(matchRev, -1, sizeof(matchRev));
        for (int i = 0; i < n; i++) {
            memset(used, 0, sizeof(used));
            if (tryMatch(i, adj)) matchCount++;
