import java.util.*;
import java.io.*;

class HungarianMatcher {
    public static final int MAX = 2000;
    int matchCount, matchPos[], matchRev[];
    boolean used[];

    public HungarianMatcher() {
        matchPos = new int[MAX];
        matchRev = new int[MAX];
        used = new boolean[MAX];
    }

    public int computeMaxMatch(int n, List<Integer>[] adj) {
        matchCount = 0;
        Arrays.fill(matchPos, -1);
        Arrays.fill(matchRev, -1);
        for (int i = 0; i < n; i++) {
            Arrays.fill(used, false);
            if (tryMatch(i, adj)) {
                matchCount++;
            }
        }
        return matchCount;
    }

    private boolean tryMatch(int u, List<Integer>[] adj) {
        for (int v : adj[u]) {
            if (!used[v]) {
                used[v] = true;
                if (matchRev[v] < 0 || tryMatch(matchRev[v], adj)) {
                    matchPos[u] = v;
                    matchRev[v] = u;
                    return true;
                }
            }
        }
        return false;
    }
}

public class Main {
    static final int INF = 1000000000;
    static final int[] deltaR = {0, -1, 0, 1};
    static final int[] deltaC = {1, 0, -1, 0};
    static int[][] gridA = new int[12][12];
    static int[][] gridB = new int[12][12];
    static int[][] distF = new int[12][12];
    static int n, t;
    static List<Integer>[] edges = new ArrayList[2000];
    static List<Integer>[][] cellGroups = new ArrayList[12][12];
    static int nNodes = 0, totalEdges = 0;

    static void floodFill(int r, int c) {
        Queue<int[]> queue = new LinkedList<>();
        for (int[] row : distF) {
            Arrays.fill(row, -1);
        }
        distF[r][c] = 0;
        queue.offer(new int[]{r, c});
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int rr = current[0], cc = current[1];
            for (int i = 0; i < 4; i++) {
                int nr = rr + deltaR[i], nc = cc + deltaC[i];
                if (gridA[nr][nc] >= 0 && distF[nr][nc] < 0) {
                    distF[nr][nc] = distF[rr][cc] + 1;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
    }

    static void assignMarks(int r, int c, int count, int t) {
        int[][] visitedV = new int[12][12];
        for (int[] row : visitedV) {
            Arrays.fill(row, -1);
        }
        Queue<int[]> queue = new LinkedList<>();
        visitedV[r][c] = 0;
        queue.offer(new int[]{r, c});
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int rr = current[0], cc = current[1];
            if (visitedV[rr][cc] > Math.min(t, distF[rr][cc])) continue;
            if (cellGroups[rr][cc] != null) {
                for (int groupIdx : cellGroups[rr][cc]) {
                    for (int i = 0; i < count; i++) {
                        edges[nNodes + i].add(groupIdx);
                    }
                }
            }
            if (visitedV[rr][cc] == Math.min(t, distF[rr][cc])) continue;
            for (int i = 0; i < 4; i++) {
                int nr = rr + deltaR[i], nc = cc + deltaC[i];
                if (gridA[nr][nc] >= 0 && visitedV[nr][nc] < 0) {
                    visitedV[nr][nc] = visitedV[rr][cc] + 1;
                    queue.offer(new int[]{nr, nc});
                }
            }
        }
        nNodes += count;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        for (int i = 0; i < 2000; i++) {
            edges[i] = new ArrayList<>();
        }
        for (int i = 0; i < 12; i++) {
            for (int j = 0; j < 12; j++) {
                cellGroups[i][j] = new ArrayList<>();
            }
        }

        for (int i = 0; i < 12; i++) {
            Arrays.fill(gridA[i], -1);
            Arrays.fill(gridB[i], -1);
        }

        int startR = -1, startC = -1;
        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                char ch = line.charAt(j - 1);
                if (ch >= '0' && ch <= '9') {
                    gridA[i][j] = ch - '0';
                }
                if (ch == 'Z') {
                    startR = i;
                    startC = j;
                }
            }
        }

        floodFill(startR, startC);

        for (int i = 0; i < 12; i++) {
            Arrays.fill(distF[i], -1);
        }

        for (int i = 1; i <= n; i++) {
            String line = br.readLine();
            for (int j = 1; j <= n; j++) {
                char ch = line.charAt(j - 1);
                if (ch >= '0' && ch <= '9') {
                    gridB[i][j] = ch - '0';
                }
                for (int k = 0; k < gridB[i][j]; k++) {
                    cellGroups[i][j].add(totalEdges++);
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (distF[i][j] < 0) {
                    distF[i][j] = INF;
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (gridA[i][j] > 0) {
                    assignMarks(i, j, gridA[i][j], t);
                }
            }
        }

        HungarianMatcher matcher = new HungarianMatcher();
        System.out.println(matcher.computeMaxMatch(totalEdges, edges));
    }
}

